using System;
using UnityEngine;
[Serializable]
public struct ParticleEmitPos
{
	public int emitCount;
	public Vector3 emitPos;
}
using UnityEngine;
public class ParticleSystemOverride
{
	public Vector3? position;
	public Vector3? localEulerAngles;
	public Vector3? startRotation3D;
	public Vector3? localScale;
	public Color32? startColor;
	public float? startRotation;
	public float? startLifetime;
	public float? startSize;
	public float? startSpeed;
	public float? radius;
	public Vector3? boxThickness;
	public float? angle;
	public float? emissionRate;
	public bool? loop;
	public string sortingLayer;
	public int? sortingOrder;
	public ParticleSystemSimulationSpace? simulationSpace;
	public ParticleSystemOverride()
	{
	}
	public ParticleSystemOverride(ParticleSystemOverride pSysOverride)
	{
		position = pSysOverride.position;
		localEulerAngles = pSysOverride.localEulerAngles;
		startRotation3D = pSysOverride.startRotation3D;
		localScale = pSysOverride.localScale;
		startColor = pSysOverride.startColor;
		startRotation = pSysOverride.startRotation;
		startLifetime = pSysOverride.startLifetime;
		startSize = pSysOverride.startSize;
		startSpeed = pSysOverride.startSpeed;
		radius = pSysOverride.radius;
		boxThickness = pSysOverride.boxThickness;
		angle = pSysOverride.angle;
		emissionRate = pSysOverride.emissionRate;
		loop = pSysOverride.loop;
		sortingLayer = pSysOverride.sortingLayer;
		sortingOrder = pSysOverride.sortingOrder;
		simulationSpace = pSysOverride.simulationSpace;
	}
	public override string ToString()
	{
		return string.Concat("position: ", position, "\nlocalEulerAngles: ", localEulerAngles, "\nstartSpeed: ", startSpeed, "\n");
	}
}
using UnityEngine;
public class PowerUpEffect : MonoBehaviour
{
	private static GameObject prefab;
	private ParticleSystem partSys;
	public Transform parentTransform;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PowerupEffect.prefab"));
	private void Awake()
	{
		partSys = GetComponent<ParticleSystem>();
		partSys.Stop(withChildren: true);
	}
	private void LateUpdate()
	{
		if (parentTransform != null)
		{
			transform.position = parentTransform.position;
		}
		else
		{
			Deactivate();
		}
	}
	public void Activate(Transform parentTrans, Color color)
	{
		parentTransform = parentTrans;
		partSys.startColor = color;
		gameObject.SetActive(value: true);
		partSys.Play(withChildren: true);
	}
	public void Deactivate()
	{
		parentTransform = null;
		partSys.Stop(withChildren: true);
		gameObject.SetActive(value: false);
	}
}
using UnityEngine;
public class RockBurstDirectionalEffect : RockDebrisEmitter
{
	public override void Emit(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null, Transform followTransform = null)
	{
		if (localEulerAngles.HasValue)
		{
			localEulerAngles = new Vector3(-90f + localEulerAngles.Value.z, -90f, 0f);
		}
		base.Emit(particleCount, position, overrides, localEulerAngles, delayTime, sortYOffset, followTransform);
	}
}
public class RockFormEffect : ParticleEffect
{
	private static ParticleSystemOverride smallSettings;
	private static ParticleSystemOverride medSettings;
	public static ParticleSystemOverride SmallSettings
	{
		get
		{
			if (smallSettings == null)
			{
				smallSettings = new ParticleSystemOverride();
				smallSettings.startSpeed = -15f;
				smallSettings.radius = 2f;
				smallSettings.startLifetime = 0.125f;
				smallSettings.emissionRate = 20f;
			}
			return smallSettings;
		}
	}
	public static ParticleSystemOverride MedSettings
	{
		get
		{
			if (medSettings == null)
			{
				medSettings = new ParticleSystemOverride();
				medSettings.startSpeed = -15f;
				medSettings.radius = 3f;
				medSettings.startLifetime = 0.2f;
				medSettings.emissionRate = 20f;
			}
			return medSettings;
		}
	}
}
using System.Collections.Generic;
using UnityEngine;
public class SmallFireballExplosion : ParticleEffect
{
	private Dictionary<ElementType, ParticleSystem> elementParticleSys;
	public override void Awake()
	{
		base.Awake();
		elementParticleSys = new Dictionary<ElementType, ParticleSystem>();
		elementParticleSys[ElementType.Neutral] = transform.Find("PurpleExplosion/FirePrimaryBlast").GetComponent<ParticleSystem>();
		elementParticleSys[ElementType.Fire] = transform.Find("RedExplosion/FirePrimaryBlast").GetComponent<ParticleSystem>();
	}
	public void EmitSingle(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null, ElementType element = ElementType.Neutral)
	{
		InitElementType(element);
		base.Emit(particleCount, position, overrides, localEulerAngles, delayTime, sortYOffset);
	}
	public void EmitSingle(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null)
	{
		EmitSingle(particleCount, position, overrides, localEulerAngles, delayTime, sortYOffset, ElementType.Neutral);
	}
	public void InitElementType(ElementType element)
	{
		if (elementParticleSys.ContainsKey(element))
		{
			effectEmitter = elementParticleSys[element];
		}
		else
		{
			effectEmitter = elementParticleSys[ElementType.Neutral];
		}
	}
}
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
public class SortParticleLayer : SortGenericLayer
{
	private Renderer psRenderer;
	public override void SetType()
	{
		type = typeof(Renderer);
		sorterType = typeof(SortParticleLayer);
	}
	public override void HandleSetSortOrder()
	{
		for (int i = 0; i < iListCount; i++)
		{
			psRenderer = (Renderer)iList[i];
			if (psRenderer != null)
			{
				psRenderer.sortingOrder = GetSortingOrder(psRenderer.transform.position.y);
			}
		}
	}
	public override void Awake()
	{
		if (sortingLayer == string.Empty)
		{
			sortingLayer = "Default";
			Debug.Log("Sorting Layer not set for: " + gameObject.name + ". Setting to Default.");
		}
		SetType();
		CreateList();
		baseTransform = transform;
		ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
		List<Renderer> list = new List<Renderer>();
		ParticleSystem[] array = componentsInChildren;
		foreach (ParticleSystem particleSystem in array)
		{
			Renderer component = particleSystem.GetComponent<Renderer>();
			if (component.sortingLayerName == sortingLayer)
			{
				list.Add(component);
			}
		}
		iList = list;
		childSorterList = GetComponentsInChildren<SortGenericLayer>().ToList();
		childSorterList.Remove(this);
	}
	public override void Start()
	{
		base.Start();
		for (int num = iList.Count - 1; num >= 0; num--)
		{
			psRenderer = (Renderer)iList[num];
			if (psRenderer.sortingLayerName != sortingLayer)
			{
				iList.RemoveAt(num);
