using UnityEngine;
public class TrailEmitter : ParticleEffect
{
	private float angleOffset;
	private ParticleSystemOverride pSysOverride;
	private float trailDist;
	private float halfTrailDist;
	private int calculatedParticleCount;
	private Vector3 angleStartPos;
	public override void Awake()
	{
		base.Awake();
		pSysOverride = new ParticleSystemOverride();
	}
	public void Emit(Vector2 startPos, Vector2 endPos, int particleCountOverride = -1)
	{
		trailDist = Vector2.Distance(startPos, endPos);
		halfTrailDist = trailDist * 0.5f;
		calculatedParticleCount = Mathf.Clamp((int)(trailDist * 3f), 5, 50);
		if (particleCountOverride != -1)
		{
			calculatedParticleCount = particleCountOverride;
		}
		angleStartPos = new Vector3(startPos.x + halfTrailDist, startPos.y);
		pSysOverride.position = (startPos + endPos) * 0.5f;
		pSysOverride.radius = halfTrailDist;
		pSysOverride.localEulerAngles = new Vector3(transform.localEulerAngles.x, transform.localEulerAngles.y, 360f - Globals.Vector3AngleWithPivot(angleStartPos, startPos, endPos) + angleOffset);
		pSysOverride.startRotation = 0f - (float)Math.PI / 180f * transform.localEulerAngles.z;
		int? particleCount = calculatedParticleCount;
		ParticleSystemOverride overrides = pSysOverride;
		base.Emit(particleCount, null, overrides);
	}
