	{
		if (parentTrans == null)
		{
			Stop();
			return;
		}
		if (ChaosStopwatch.Check(vortexStopwatchID))
		{
			PlayImmediate();
		}
		if (isPlaying)
		{
			calcRadius = Mathf.Lerp(startRadius, endRadius, ChaosStopwatch.GetTimePercentage(vortexStopwatchID));
