using UnityEngine;
public class LightningChain : MonoBehaviour
{
	private static GameObject prefab;
	public ParticleSystem emitter;
	private ParticleSystem.EmissionModule emitMod;
	private ParticleSystem.ShapeModule shapeMod;
	public Attack attack;
	public BoxCollider2D attackCollider;
	public Transform followTrans;
	public Transform targetTrans;
	private static float startOffset = 0.75f;
	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(10f);
	private bool destroyQueued;
	private float attackWidth = 0.8f;
	private float attackDist;
	private float halfDist;
	private Vector2 attackVector;
	private Vector2 localPos;
	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.125f);
	private AudioSource loopAudio;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningChain.prefab"));
	private void Awake()
	{
		emitMod = emitter.emission;
		shapeMod = emitter.shape;
		localPos = Vector2.zero;
	}
	private void Start()
	{
		lifeStopwatch.IsRunning = true;
		attackCollider.enabled = true;
	}
	private void FixedUpdate()
	{
		if (!destroyQueued && !lifeStopwatch.IsRunning)
		{
			Reset();
		}
	}
	private void LateUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (followTrans != null)
		{
			transform.position = followTrans.position;
		}
		if (targetTrans != null)
		{
			SetAttack();
		}
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			if (loopAudio == null || loopAudio.clip.name != "BallLightningLoop")
			{
				loopAudio = SoundManager.PlayWithDistAndSPR("BallLightningLoop", transform.position);
			}
			else
			{
				loopAudio.Play();
			}
		}
	}
	private void SetAttack()
	{
		attackVector = targetTrans.position - transform.position;
		attackDist = attackVector.magnitude;
		attackVector.Normalize();
		transform.localEulerAngles = Globals.GetRotationVector(attackVector);
		attack.knockbackOverwriteVector = attackVector;
		halfDist = attackDist * 0.5f;
		attackCollider.size = new Vector2(attackWidth, attackDist);
		attackCollider.offset = new Vector2(0f, halfDist);
		localPos.y = halfDist + startOffset;
		emitter.transform.localPosition = localPos;
		emitMod.rateOverTime = attackDist * 50f;
		shapeMod.radius = halfDist - startOffset;
	}
	public void Reset()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			emitter.Stop();
			attackCollider.enabled = false;
			EmitLineBurst();
			Object.Destroy(gameObject, 1f);
		}
	}
	public void EmitLineBurst(int givenCount = 4)
	{
		SoundManager.PlayWithDistAndSPR("Shockwave", transform.position);
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect");
		Vector2 a = transform.position;
		Vector2 b = ((!(targetTrans == null)) ? targetTrans.position : transform.position);
		for (int i = 1; i < 8; i++)
		{
			poolItem.Emit(givenCount, Vector2.Lerp(a, b, (float)i * 0.125f));
		}
	}
}

