public class LightningArcanaCountItem : EleArcanaUnlockCountItem
{
	public static string staticID = "LightningArcanaCountItem";
	private static string hsFieldStr = "hitStunDurationModifier";
	private static string odFieldStr = "overdriveProgressMultiplier";
	private NumVarStatMod hitStunMod;
	private NumVarStatMod overdriveMod;
	private bool modApplied;
	public LightningArcanaCountItem()
		: base(staticID, ElementType.Lightning)
	{
		category = Category.Offense;
		hitStunMod = new NumVarStatMod(staticID, 3f);
		overdriveMod = new NumVarStatMod(staticID, 1f, 10, VarStatModType.Multiplicative);
	}
	public override bool SetStatus(bool givenStatus)
	{
		if (!base.SetStatus(givenStatus))
		{
			return false;
		}
		Player player = parentPlayer;
		player.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
		Player player2 = parentPlayer;
		player2.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player2.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
		if (givenStatus)
		{
			Player player3 = parentPlayer;
			player3.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player3.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
			Player player4 = parentPlayer;
			player4.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player4.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
		}
		return true;
	}
	private void OnSkillEnter(Player.SkillState givenSkill)
	{
		modApplied = UnityEngine.Random.value < chanceMod.modValue && givenSkill != null && givenSkill.skillData != null && !givenSkill.isBasic && !givenSkill.isDash;
		if (modApplied)
		{
			givenSkill.skillData.AddMod(hsFieldStr, hitStunMod);
			givenSkill.skillData.AddMod(odFieldStr, overdriveMod);
			LightningBurst.CreateBurst(parentPlayer.attackOriginTrans.position, string.Empty, string.Empty).playAudio = false;
			Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, null, parentPlayer.transform.position);
		}
	}
	private void OnSkillExit(Player.SkillState givenSkill)
	{
		if (modApplied && givenSkill != null && givenSkill.skillData != null)
		{
			givenSkill.skillData.RemoveMod(hsFieldStr, staticID);
			givenSkill.skillData.RemoveMod(odFieldStr, staticID);
		}
	}
