		{
			parent.anim.Play("HammerEnd", -1, 0f);
			PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Emit(3, parent.transform.position + Vector3.up * 2f + Globals.Vector3LeftHalf * parent.transform.localScale.x);
		}
		else
		{
			parent.anim.Play("BatThrow", -1, 0f);
		}
		break;
	}
