			case StopwatchState.Ready:
				attack.collider.enabled = false;
				PlayEffects();
				break;
			case StopwatchState.Done:
				Disable();
				break;
			}
		}
	}
	public void StartMovement()
	{
		if (!moveStarted)
		{
			moveStarted = true;
			moveStopwatch.IsRunning = true;
			followOffset *= 0f - ((!isEmpowered) ? 1.5f : 2f);
		}
	}
	public void Activate()
	{
		isActivated = true;
		if (isUltimate)
		{
			anim.Play("AttackUlt", -1, 0f);
			ultEffect.reqFollowTrans = true;
			ParticleEffect particleEffect = ultEffect;
			float? emissionRate = 60f;
			Transform followTransform = transform;
			particleEffect.Play(emissionRate, null, null, null, followTransform);
		}
		else if (isEmpowered)
		{
			anim.Play("AttackLarge", -1, 0f);
		}
		else
		{
			anim.Play("Attack", -1, 0f);
		}
		hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, maxHitCount);
		attack.collider.enabled = true;
		if (lightPartSys != null)
		{
			shapeMod = lightPartSys.shape;
			shapeMod.radius = ((!isEmpowered) ? 1.4f : 2.25f);
			lightPartSys.Play();
		}
		LightningBurst.CreateBurst(transform.position, string.Empty, string.Empty, 1, 2f);
		if (isUltimate)
		{
			ultSpawnStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, maxHitCount);
		}
		if (!isChild)
		{
			CameraController.ShakeCamera(0.5f);
			PlayEffects();
		}
	}
	public void Disable()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			attack.collider.enabled = false;
			spriteRenderer.enabled = false;
			followTrans = null;
			lightPartSys.Stop();
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, transform.position, ParticleEffectOverrides.RadiusOne);
			Vector3 position = transform.position;
			float givenScale = ((!isEmpowered) ? 1.25f : 1.75f);
			LightningBurst.CreateBurst(position, string.Empty, string.Empty, 1, givenScale);
			light.enabled = false;
			Object.Destroy(gameObject, destroyDelay);
			ultEffect.Stop();
		}
	}
	private void PlayEffects()
	{
		string audioID = "LightningBurst";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(0.85f, 1.15f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, transform.position, ParticleEffectOverrides.Radius0p75);
	}
}

