	private void UpdateFacingDir()
	{
		if (targetTrans == null)
		{
			facingDirStr = "Down";
			return;
		}
		facingDirStr = Globals.GetPrimaryDirection((targetTrans.position - transform.position).normalized).ToString();
		if (facingDirStr == "Left")
		{
			transform.localScale = Globals.ScaleVecFlipX;
		}
	}
