			currentPosition = transform.position;
			targetPosition = targetVector * 0.5f + ((!(targetTrans == null) && !(Vector2.SqrMagnitude(transform.position - targetTrans.position) > 100f)) ? ((Vector2)targetTrans.position) : currentPosition);
