			endPos = currentPosition;
			startPos = targetPosition;
			delayTime = dashTime * 0.2f;
			poolItem2.Emit(endPos, startPos, -1, emitEveryOther: true, -1f, snapToFit: true, -1f, delayTime);
			SoundManager.PlayAudioWithDistance("TeleStrike", currentPosition);
		}
	}
	private void FixedUpdate()
	{
		if (dashStarted && !dashCompleted && movement.MoveToTarget(targetPosition, 0.5f))
		{
			dashCompleted = true;
			Reset();
		}
	}
	public void Reset()
	{
		currentPosition = transform.position;
		if (useBurst)
		{
			LightningBurst.CreateBurst(currentPosition, skillCat, skillID, burstLevRadius, burstLevRadius);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, currentPosition, ParticleEffectOverrides.RadiusOne);
