	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningSwordSummon.prefab"));
	private void Start()
	{
		attackCol.enabled = true;
		if (isUlt)
		{
			delayStopwatchID = ChaosStopwatch.Begin(orbitDelay * 6f + atkDelay);
		}
		else
		{
			delayStopwatchID = ChaosStopwatch.Begin(orbitDelay * 2.5f);
		}
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(1, attack.transform.position - (Vector3)attackVec * (movement.orbitRadius - 1f));
		SoundManager.PlayWithDistAndSPR("LightningBurst", transform.position, 1.2f);
	}
	private void FixedUpdate()
	{
		if (!orbitCompleted)
		{
			HandleTargetting();
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				orbitCompleted = true;
				movement.orbit = false;
				movement.dashVector = attackVec;
				attack.knockbackOverwriteVector = attackVec;
				attackCol.enabled = false;
				if (isUlt)
				{
					attack.ChangeAttackInfoLevel(4);
				}
				attackCol.enabled = true;
			}
		}
		else if (!moveCompleted && movement.DashToTarget())
